// SettleClear takes a queued clear out of the queue as state, settled at settled_at.
func (q *Queries) SettleClear(ctx context.Context, arg SettleClearParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, settleClear,
		arg.State,
		arg.SettledAt,
		arg.SentAt,
		arg.Error,
		arg.SkipReason,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const skipOtherAccountsQueued = `-- name: SkipOtherAccountsQueued :execrows
UPDATE gh_thread_clears
SET state = 'skipped', settled_at = ?1, skip_reason = ?2
WHERE state = 'queued' AND account_login <> ?3 AND queued_at < ?4
`

type SkipOtherAccountsQueuedParams struct {
	SettledAt    *time.Time
	SkipReason   string
	AccountLogin string
	Before       time.Time
}

// SkipOtherAccountsQueued skips the queued clears of every account but the one given that
// were queued before before: the account they wait for hasn't come back.
func (q *Queries) SkipOtherAccountsQueued(ctx context.Context, arg SkipOtherAccountsQueuedParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, skipOtherAccountsQueued,
		arg.SettledAt,
		arg.SkipReason,
		arg.AccountLogin,
		arg.Before,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

