const upsertMoment = `-- name: UpsertMoment :exec
INSERT INTO gh_thread_moments (account_login, repo_owner, repo_name, item_kind, number, trigger, at, created_at)
VALUES (?, ?, ?, ?, ?, ?, ?, ?)
ON CONFLICT (account_login, repo_owner, repo_name, item_kind, number, trigger) DO UPDATE SET
    at = excluded.at,
    created_at = excluded.created_at
`

type UpsertMomentParams struct {
	AccountLogin string
	RepoOwner    string
	RepoName     string
	ItemKind     string
	Number       int64
	Trigger      string
	At           time.Time
	CreatedAt    time.Time
}

// UpsertMoment records that the user finished an item in the app, by trigger, at, heard of
// at created_at: a later moment of the same trigger replaces the one before.
func (q *Queries) UpsertMoment(ctx context.Context, arg UpsertMomentParams) error {
	_, err := q.db.ExecContext(ctx, upsertMoment,
		arg.AccountLogin,
		arg.RepoOwner,
		arg.RepoName,
		arg.ItemKind,
		arg.Number,
		arg.Trigger,
		arg.At,
		arg.CreatedAt,
	)
	return err
}
